class TreeNode:
    def __init__(self, val: int = 0, left: "TreeNode | None" = None, right: "TreeNode | None" = None):
        self.val = val
        self.left = left
        self.right = right


def trim_band(root: TreeNode | None, lo: int, hi: int) -> TreeNode | None:
    if root is None:
        return None
    if root.val < lo:
        # Too cheap: so is everything on its left. Only the right subtree can hold
        # prices in the band, and its trimmed version takes this node's place.
        return trim_band(root.right, lo, hi)
    if root.val > hi:
        return trim_band(root.left, lo, hi)
    root.left = trim_band(root.left, lo, hi)
    root.right = trim_band(root.right, lo, hi)
    return root

