use std::cell::RefCell;
use std::rc::Rc;

fn trim_band(root: Option<Rc<RefCell<TreeNode>>>, lo: i32, hi: i32) -> Option<Rc<RefCell<TreeNode>>> {
    let node = root?;
    let val = node.borrow().val;
    if val < lo {
        // Too cheap: so is everything on its left. Only the right subtree can hold
        // prices in the band, and its trimmed version takes this node's place.
        let right = node.borrow_mut().right.take();
        return trim_band(right, lo, hi);
    }
    if val > hi {
        let left = node.borrow_mut().left.take();
        return trim_band(left, lo, hi);
    }
    let (left, right) = {
        let mut n = node.borrow_mut();
        (n.left.take(), n.right.take())
    };
    let (left, right) = (trim_band(left, lo, hi), trim_band(right, lo, hi));
    {
        let mut n = node.borrow_mut();
        n.left = left;
        n.right = right;
    }
    Some(node)
}

