class TreeNode:
    def __init__(self, val: int = 0, left: "TreeNode | None" = None, right: "TreeNode | None" = None):
        self.val = val
        self.left = left
        self.right = right


def trim_band(root: TreeNode | None, lo: int, hi: int) -> TreeNode | None:
    # 1. Walk down until the root itself is in the band.
    while root and not lo <= root.val <= hi:
        root = root.right if root.val < lo else root.left
    if root is None:
        return None
    # 2. Everything left of the root is <= hi, so only lo can cut there: follow
    #    the left spine, splicing each too-cheap node out for its right subtree.
    cur = root
    while cur.left:
        if cur.left.val < lo:
            cur.left = cur.left.right
        else:
            cur = cur.left
    # 3. The mirror image on the right, against hi.
    cur = root
    while cur.right:
        if cur.right.val > hi:
            cur.right = cur.right.left
        else:
            cur = cur.right
    return root

