use std::cell::RefCell;
use std::rc::Rc;

fn trim_band(mut root: Option<Rc<RefCell<TreeNode>>>, lo: i32, hi: i32) -> Option<Rc<RefCell<TreeNode>>> {
    // 1. Walk down until the root itself is in the band.
    while let Some(node) = root.clone() {
        let val = node.borrow().val;
        if val < lo {
            root = node.borrow().right.clone();
        } else if val > hi {
            root = node.borrow().left.clone();
        } else {
            break;
        }
    }
    let root = root?;
    // 2. Everything left of the root is <= hi, so only lo can cut there: follow
    //    the left spine, splicing each too-cheap node out for its right subtree.
    let mut cur = Rc::clone(&root);
    loop {
        let Some(left) = cur.borrow().left.clone() else { break };
        if left.borrow().val < lo {
            cur.borrow_mut().left = left.borrow().right.clone();
        } else {
            cur = left;
        }
    }
    // 3. The mirror image on the right, against hi.
    let mut cur = Rc::clone(&root);
    loop {
        let Some(right) = cur.borrow().right.clone() else { break };
        if right.borrow().val > hi {
            cur.borrow_mut().right = right.borrow().left.clone();
        } else {
            cur = right;
        }
    }
    Some(root)
}
